query:
query matchdetailsRugbyComAu($comp: CompInput) {
  getFixtureItem(comp: $comp) {
    ...Fixtures_fixture
    __typename
  }
  allMatchCommentary(comp: $comp) {
    ...Fixture_MatchCommentary
    __typename
  }
  allMatchStatsSummary(comp: $comp) {
    id
    lineUp {
      id
      players {
        ...MatchLineup_matchplayer
        __typename
      }
      substitutes {
        ...MatchLineup_matchplayer
        __typename
      }
      coaches {
        ...MatchLineup_matchplayer
        __typename
      }
      __typename
    }
    referees {
      ...MatchStatsSummary_matchreferee
      __typename
    }
    pointsSummary {
      id
      tries {
        ...PointSummary_matchpoint
        __typename
      }
      conversions {
        ...PointSummary_matchpoint
        __typename
      }
      penaltyGoals {
        ...PointSummary_matchpoint
        __typename
      }
      fieldGoals {
        ...PointSummary_matchpoint
        __typename
      }
      __typename
    }
    playSummary {
      id
      attack {
        ...MatchPlaySummary_matchplaystat
        __typename
      }
      defence {
        ...MatchPlaySummary_matchplaystat
        __typename
      }
      kicking {
        ...MatchPlaySummary_matchplaystat
        __typename
      }
      breakdown {
        ...MatchPlaySummary_matchplaystat
        __typename
      }
      setPlay {
        ...MatchPlaySummary_matchplaystat
        __typename
      }
      possession {
        ...MatchPlaySummary_matchplaystat
        __typename
      }
      discipline {
        ...MatchPlaySummary_matchplaystat
        __typename
      }
      __typename
    }
    __typename
  }
  allSeasonStat(comp: $comp) {
    ...MatchPlaySummary_matchplaystat
    __typename
  }
}

fragment Fixtures_fixture on FixtureItem {
  id
  compId
  compName
  dateTime
  group
  isLive
  isBye
  round
  roundType
  roundLabel
  season
  status
  venue
  sourceType
  matchLabel
  homeTeam {
    ...Fixtures_team
    __typename
  }
  awayTeam {
    ...Fixtures_team
    __typename
  }
  fixtureMeta {
    ...Fixtures_meta
    __typename
  }
  __typename
}

fragment Fixtures_team on Team {
  id
  name
  teamId
  score
  crest
  __typename
}

fragment Fixtures_meta on Fixture {
  id
  ticketURL
  ticketsAvailableDate
  isSoldOut
  radioURL
  radioStart
  radioEnd
  streamURL
  streamStart
  streamEnd
  broadcastPartners {
    ...Fixtures_broadcastPartners
    __typename
  }
  __typename
}

fragment Fixtures_broadcastPartners on BroadcastPartner {
  id
  name
  link
  photoId
  __typename
}

fragment Fixture_MatchCommentary on MatchCommentary {
  id
  minute
  type
  comment
  __typename
}

fragment MatchLineup_matchplayer on MatchPlayer {
  id
  name
  position
  shirtNumber
  isHome
  photo {
    id
    url
    alt
    __typename
  }
  link
  captainType
  frontRow
  __typename
}

fragment PointSummary_matchpoint on MatchPoint {
  id
  playerName
  isHome
  pointsMinute
  __typename
}

fragment MatchPlaySummary_matchplaystat on MatchPlayStat {
  id
  title
  homeValue
  awayValue
  __typename
}

fragment MatchStatsSummary_matchreferee on MatchReferee {
  refereeId
  type
  refereeName
  status
  notified
  private
  isActive
  __typename
}
